using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Grasshopper.Kernel;

namespace BenchPlugin
{
    public class AsyncStatsComponent : GH_Component
    {
        private CancellationTokenSource _cts;
        private double[] _pending;
        private double[] _resultFor;
        private (double Mean, double StdDev)? _result;

        public AsyncStatsComponent()
            : base("Async Stats", "AsyncStats",
                "Mean and standard deviation of a list of numbers, computed asynchronously",
                "Bench", "Data")
        {
        }

        public override Guid ComponentGuid => new Guid("6f0c2b0e-3d7a-4c55-9a1e-5b7f1d2a8c41");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddNumberParameter("Values", "V", "List of numbers", GH_ParamAccess.list);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Mean", "M", "Arithmetic mean", GH_ParamAccess.item);
            pManager.AddNumberParameter("StdDev", "S", "Population standard deviation", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess da)
        {
            var values = new List<double>();
            if (!da.GetDataList(0, values)) return;
            var input = values.ToArray();

            // Task finished for these inputs: publish the result.
            if (_result.HasValue && _resultFor != null && _resultFor.SequenceEqual(input))
            {
                da.SetData(0, _result.Value.Mean);
                da.SetData(1, _result.Value.StdDev);
                return;
            }

            // Same inputs already being computed: wait for it to finish.
            if (_pending != null && _pending.SequenceEqual(input)) return;

            // Inputs changed: cancel the previous computation and start a new one.
            _cts?.Cancel();
            _cts?.Dispose();
            var cts = new CancellationTokenSource();
            _cts = cts;
            _pending = input;
            _result = null;
            _resultFor = null;

            var token = cts.Token;
            Task.Run(() => Compute(input, token), token).ContinueWith(t =>
            {
                if (t.IsCanceled || t.IsFaulted || token.IsCancellationRequested) return;
                var doc = OnPingDocument();
                if (doc == null) return;
                doc.ScheduleSolution(1, d =>
                {
                    if (token.IsCancellationRequested) return;
                    _result = t.Result;
                    _resultFor = input;
                    _pending = null;
                    ExpireSolution(false);
                });
            }, TaskScheduler.Default);

            Message = "Computing...";
        }

        private static (double Mean, double StdDev) Compute(double[] values, CancellationToken token)
        {
            if (values.Length == 0) return (0, 0);
            double sum = 0;
            for (int i = 0; i < values.Length; i++)
            {
                if ((i & 0xFFFF) == 0) token.ThrowIfCancellationRequested();
                sum += values[i];
            }
            double mean = sum / values.Length;
            double sq = 0;
            for (int i = 0; i < values.Length; i++)
            {
                if ((i & 0xFFFF) == 0) token.ThrowIfCancellationRequested();
                double d = values[i] - mean;
                sq += d * d;
            }
            return (mean, Math.Sqrt(sq / values.Length));
        }

        protected override void AfterSolveInstance()
        {
            if (_result.HasValue) Message = null;
        }
    }
}
